"""What-if screen: would this resistance mutation matter for this drug? Evidence, not a score.

    drug + target + mutation
        1. read the mutation            (core/ranking/targets: notation, kind)
        2. is it documented in CARD?    (the caller passes CARD's mutation list for the determinant)
        3. does a mutant structure exist?   (app/worker targets.json: say so and skip, never fake)
        4. what does the literature say?    (evidence.rag: retrieve cards, model, quote check)
        5. docking support, only if real WT and mutant runs with redocking controls were supplied

Every step is recorded in ``steps`` with its status, so a reader sees what ran, what was skipped
and why. The model is used in exactly one step (4) and its reply goes through the same quote
check as the rest of the evidence package: a claim survives only if its quote is on a retrieved
card. The planner is plain code, not a model, so which steps run cannot be talked into changing.

What this is not. The result is ``what_if_support_only`` with ``included_in_primary_rank``
false, and nothing here imports the ranker. The pre-registered ranking is pinned by checksum
(see docs/resistance-risk.md); wiring a signal into it needs an amendment first. The verdict is
an ordinal label, never a probability, and it says nothing about efficacy or a patient.

    python -m evidence.whatif linezolid --target gyrb-saureus --mutation T165I \\
        --cache data/evidence/whatif --mode replay
"""

from __future__ import annotations

import json
from pathlib import Path

from ranking.targets import MutationParseError, parse_mutation

QUESTION = "mutation_effect"
QUESTION_WORDS = "resistance resistant reduced susceptibility MIC substitution mutation"

# Ordinal evidence labels. Order matters only for reading; there is no arithmetic on them.
LITERATURE_SUPPORTED = "literature_supported"
DOCUMENTED_ONLY = "documented_only"
NO_EVIDENCE = "no_evidence"
NOT_ASSESSED = "not_assessed"

DONE, SKIPPED, FAILED = "done", "skipped", "failed"


def step(name: str, status: str, detail: str, **extra) -> dict:
    return {"step": name, "status": status, "detail": detail, **extra}


def find_target(registry: dict, target: str) -> dict | None:
    """A registry entry by id or CARD determinant, case-insensitively."""
    wanted = target.strip().lower()
    for entry in registry.get("targets", []):
        if wanted in (entry["id"].lower(), (entry.get("card_determinant") or "").lower()):
            return entry
    return None


def structure_step(entry: dict | None, mutation) -> dict:
    """The mutant-structure question. Anything but a matching recorded entry is a skip."""
    if entry is None:
        return step("mutant_structure", SKIPPED,
                    "this target is not in the structure registry, so no structure is assumed")
    mutant = entry["mutant"]
    status = mutant["status"]
    if status == "exists":
        recorded = [m.strip().upper() for m in mutant.get("mutations", [])]
        if mutation.raw.upper() in recorded:
            return step("mutant_structure", DONE,
                        f"mutant structure {mutant['pdb_id']} records {mutation.raw}",
                        pdb_id=mutant["pdb_id"], wild_type_pdb_id=entry["wild_type"].get("pdb_id"))
        return step("mutant_structure", SKIPPED,
                    f"structure {mutant['pdb_id']} exists but records {recorded or 'no mutation'}, "
                    f"not {mutation.raw}; it is not used as a stand-in")
    return step("mutant_structure", SKIPPED, f"{status}: {mutant.get('reason') or 'no reason recorded'}")


def documented_step(mutation, known: list | None) -> dict:
    """Is the mutation in the list CARD gives for this determinant (same position and change)?"""
    if known is None:
        return step("card_lookup", SKIPPED, "no CARD mutation list was supplied for this determinant")
    parsed = []
    for text in known:
        try:
            parsed.append(parse_mutation(text))
        except MutationParseError:
            continue            # unreadable CARD notation is not a match; the caller sees the count
    hits = [m for m in parsed if (m.position, m.wild_type, m.variant) ==
            (mutation.position, mutation.wild_type, mutation.variant)]
    same_site = sorted({m.raw for m in parsed if m.position == mutation.position} - {mutation.raw})
    if hits:
        return step("card_lookup", DONE, f"{mutation.raw} is documented in CARD",
                    documented=True, checked=len(known))
    note = (f"; other documented changes at position {mutation.position}: {', '.join(same_site)}"
            if same_site else "")
    return step("card_lookup", DONE, f"{mutation.raw} is not in the supplied CARD list{note}",
                documented=False, checked=len(known), same_position=same_site)


def literature_step(retrieve, drug: str, mutation, determinant: str | None) -> dict:
    """Run the RAG question. ``retrieve(drug, query) -> dict`` is ``answer_question``'s result."""
    if retrieve is None:
        return step("literature", SKIPPED, "no retriever was supplied", claims=[])
    query = f"{determinant or ''} {mutation.raw} {QUESTION_WORDS}".strip()
    found = retrieve(drug, query)
    if "error" in found:
        return step("literature", FAILED, f"the model call failed: {found['error']}", claims=[])
    cited = [c if isinstance(c, dict) else c.as_dict() for c in found["claims"]]
    cited = [c for c in cited if c["answer"].strip().lower() != "no record found"]
    detail = (f"{len(cited)} cited claim(s) from {len(found.get('retrieved', []))} passage(s)"
              if cited else "no retrieved card answered the question (no record found)")
    return step("literature", DONE, detail, claims=cited, rejected=found.get("rejected", []),
                injections=found.get("injections", []), retrieved=found.get("retrieved", []))


def docking_step(observations: list | None, mutation) -> dict:
    """Docking support only from real runs the caller measured; this module never docks."""
    if not observations:
        return step("docking_support", SKIPPED,
                    "no measured wild-type and mutant docking runs were supplied")
    from eval.docking_support import supporting_signal      # lazy: pure stdlib, but a separate package
    chosen = [o for o in observations if o.variant == "wild_type" or
              (o.mutation or "").upper() == mutation.raw.upper()]
    if not any(o.variant == "mutant" for o in chosen):
        return step("docking_support", SKIPPED, f"no mutant run for {mutation.raw} was supplied")
    signal = supporting_signal(chosen)
    comparison = signal["comparisons"][0]
    return step("docking_support", DONE if comparison["status"] == "supporting_only" else SKIPPED,
                comparison["caveat"], signal=signal)


def verdict(card: dict, literature: dict) -> str:
    """An ordinal label from evidence that was actually found. Never a probability."""
    if literature["status"] == DONE and literature.get("claims"):
        return LITERATURE_SUPPORTED
    if card.get("documented"):
        return DOCUMENTED_ONLY
    if card["status"] == DONE or literature["status"] == DONE:
        return NO_EVIDENCE
    return NOT_ASSESSED


def what_if(drug: str, target: str, mutation_text: str, *, registry: dict,
            known_mutations: list | None = None, retrieve=None,
            observations: list | None = None) -> dict:
    """Screen one drug / target / mutation. Each step is independent and a skip is explicit."""
    try:
        mutation = parse_mutation(mutation_text)
    except MutationParseError as exc:
        return {"drug": drug, "target": target, "mutation": mutation_text, "verdict": NOT_ASSESSED,
                "steps": [step("parse", FAILED, str(exc))], **_FIXED}

    entry = find_target(registry, target)
    steps = [step("parse", DONE, f"{mutation.raw}: {mutation.wild_type}{mutation.position}"
                                 f"{mutation.variant} ({mutation.kind})")]
    card = documented_step(mutation, known_mutations)
    structure = structure_step(entry, mutation)
    literature = literature_step(retrieve, drug, mutation, entry.get("card_determinant") if entry else None)
    docking = docking_step(observations, mutation)
    steps += [card, structure, literature, docking]
    return {"drug": drug, "target": target, "mutation": mutation.raw,
            "verdict": verdict(card, literature), "steps": steps, **_FIXED}


# Fixed on every result, so no caller can present this as a ranking input or a prediction.
_FIXED = {"signal_type": "what_if_support_only", "included_in_primary_rank": False,
          "ordinal": True,
          "limitations": "Evidence screen only: no efficacy, MIC, patient outcome or probability "
                         "is inferred. A skipped step is a gap, not a negative."}


def rag_retriever(corpus, model, *, k: int = 6, log=None):
    """The ``retrieve`` callable for a built ``evidence.rag.Corpus``."""
    from .rag import answer_question

    def retrieve(drug: str, query: str) -> dict:
        return answer_question(corpus, model, drug, QUESTION, k=k, log=log, query=query)
    return retrieve


def render(result: dict) -> str:
    lines = [f"{result['drug']} / {result['target']} / {result['mutation']}: {result['verdict']}"]
    for s in result["steps"]:
        lines.append(f"  [{s['status']:7}] {s['step']}: {s['detail']}")
        for claim in s.get("claims", []):
            lines.append(f"      {claim['answer'][:110]}\n      <{claim['url']}>")
    lines.append(f"  {result['limitations']}")
    return "\n".join(lines)


def main(argv=None) -> int:
    import argparse
    import sys

    from .rag import Corpus, baseline_model, queries_for
    from .session import LIVE, RECORD, REPLAY, Session, StepLog

    parser = argparse.ArgumentParser(prog="python -m evidence.whatif",
                                     description=__doc__.split("\n")[0])
    parser.add_argument("drug")
    parser.add_argument("--target", required=True, help="registry id or CARD determinant")
    parser.add_argument("--mutation", required=True, help="e.g. S84L or Ser84Leu")
    parser.add_argument("--card-mutations", type=Path, help="JSON list of CARD mutation strings")
    parser.add_argument("--cache", type=Path, required=True)
    parser.add_argument("--mode", default=REPLAY, choices=[LIVE, RECORD, REPLAY])
    parser.add_argument("--out", type=Path)
    args = parser.parse_args(argv)

    from htb_worker.targets import load
    known = json.loads(args.card_mutations.read_text("utf-8")) if args.card_mutations else None
    log = StepLog()
    try:
        registry = load()
        entry = find_target(registry, args.target)
        context = f"{entry.get('card_determinant', '') if entry else ''} {args.mutation}"
        with Session(args.cache, mode=args.mode, log=log) as session:
            corpus = Corpus.build(session, queries_for(args.drug, context))
            result = what_if(args.drug, args.target, args.mutation, registry=registry,
                             known_mutations=known,
                             retrieve=rag_retriever(corpus, baseline_model, log=log))
    except Exception as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 2
    result["model"] = "keyword-baseline"
    print(render(result))
    if args.out:
        args.out.parent.mkdir(parents=True, exist_ok=True)
        args.out.write_text(json.dumps(result, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

