"""The what-if screen: its steps, its refusals, and that it stays out of the ranking.

The retriever is a stub, so nothing here needs LangChain, a browser, a key or the network.
"""

import json
from pathlib import Path

from evidence.whatif import (DOCUMENTED_ONLY, LITERATURE_SUPPORTED, NO_EVIDENCE, NOT_ASSESSED,
                             render, what_if)

REAL_REGISTRY = json.loads(
    (Path(__file__).resolve().parents[1] / "app/worker/structures/targets.json").read_text("utf-8"))

REGISTRY = {"targets": [
    {"id": "gyr-a", "card_determinant": "gyrA",
     "wild_type": {"status": "exists", "pdb_id": "1AAA"},
     "mutant": {"status": "exists", "pdb_id": "2BBB", "mutations": ["S84L"]}},
    {"id": "pbp", "card_determinant": "mecA", "wild_type": {"status": "exists", "pdb_id": "3ZG5"},
     "mutant": {"status": "not_applicable", "pdb_id": None, "mutations": [],
                "reason": "target replacement, not alteration"}},
]}

CLAIM = {"question": "mutation_effect", "answer": "S84L raised the ciprofloxacin MIC",
         "quote": "the S84L substitution raised the MIC", "url": "https://pubmed.example/1",
         "source": "pubmed", "candidate": "ciprofloxacin"}


def retriever(claims=(), error=None):
    calls = []

    def retrieve(drug, query):
        calls.append((drug, query))
        if error:
            return {"claims": [], "error": error}
        return {"claims": list(claims), "rejected": [], "injections": [], "retrieved": [{"url": "u"}]}
    retrieve.calls = calls
    return retrieve


def steps(result):
    return {s["step"]: s for s in result["steps"]}


def test_a_cited_claim_is_literature_supported():
    r = what_if("ciprofloxacin", "gyrA", "S84L", registry=REGISTRY, retrieve=retriever([CLAIM]))
    assert r["verdict"] == LITERATURE_SUPPORTED
    assert steps(r)["literature"]["claims"][0]["url"] == "https://pubmed.example/1"


def test_the_retrieval_query_names_the_mutation_and_the_determinant():
    stub = retriever()
    what_if("ciprofloxacin", "gyr-a", "Ser84Leu", registry=REGISTRY, retrieve=stub)
    drug, query = stub.calls[0]
    assert drug == "ciprofloxacin" and "gyrA" in query and "S84L" in query


def test_card_only_is_documented_only_and_no_record_is_not_a_claim():
    no_record = {**CLAIM, "answer": "no record found", "quote": None}
    r = what_if("ciprofloxacin", "gyrA", "S84L", registry=REGISTRY, known_mutations=["S84L", "D88N"],
                retrieve=retriever([no_record]))
    assert r["verdict"] == DOCUMENTED_ONLY and steps(r)["literature"]["claims"] == []


def test_checked_but_nothing_found_is_no_evidence_not_unassessed():
    r = what_if("ciprofloxacin", "gyrA", "S84F", registry=REGISTRY, known_mutations=["S84L"],
                retrieve=retriever())
    assert r["verdict"] == NO_EVIDENCE
    assert steps(r)["card_lookup"]["same_position"] == ["S84L"]


def test_nothing_run_is_not_assessed():
    r = what_if("ciprofloxacin", "gyrA", "S84L", registry=REGISTRY)
    assert r["verdict"] == NOT_ASSESSED
    assert steps(r)["literature"]["status"] == "skipped"


def test_unreadable_notation_stops_with_a_failed_parse():
    r = what_if("ciprofloxacin", "gyrA", "banana", registry=REGISTRY, retrieve=retriever([CLAIM]))
    assert r["verdict"] == NOT_ASSESSED and r["steps"][0]["status"] == "failed"
    assert len(r["steps"]) == 1


def test_a_failed_model_call_is_a_failed_step_not_a_negative():
    r = what_if("ciprofloxacin", "gyrA", "S84L", registry=REGISTRY, retrieve=retriever(error="timeout"))
    assert steps(r)["literature"]["status"] == "failed"


def test_mutant_structure_is_used_only_for_the_mutation_it_records():
    same = what_if("c", "gyrA", "S84L", registry=REGISTRY)
    other = what_if("c", "gyrA", "D88N", registry=REGISTRY)
    assert steps(same)["mutant_structure"]["status"] == "done"
    assert steps(same)["mutant_structure"]["pdb_id"] == "2BBB"
    skipped = steps(other)["mutant_structure"]
    assert skipped["status"] == "skipped" and "not used as a stand-in" in skipped["detail"]


def test_not_applicable_and_unknown_targets_are_skipped_with_the_reason():
    assert "target replacement" in steps(what_if("c", "mecA", "G246E", registry=REGISTRY))["mutant_structure"]["detail"]
    assert steps(what_if("c", "nope", "G246E", registry=REGISTRY))["mutant_structure"]["status"] == "skipped"


def test_the_real_registry_has_no_mutant_structure_so_every_real_target_skips():
    for target in REAL_REGISTRY["targets"]:
        r = what_if("c", target["id"], "S84L", registry=REAL_REGISTRY)
